"""Install a task-scoped continuous collector; run only on the development host."""
from pathlib import Path
import datetime, json, os, secrets, shutil, socket, subprocess
assert socket.gethostname()=='mssc'
root=Path('/data/ops-v12-native-visual-r24-20261026');work=root/'r49';private=work/'private'
work.mkdir(exist_ok=False);private.mkdir(mode=0o700)
for name in ['victoria-data','collector-data','bin']:(work/name).mkdir(mode=0o700)
shutil.copy('/tmp/ops-r49-vlagent',work/'bin/vlagent');os.chmod(work/'bin',0o755);os.chmod(work/'bin/vlagent',0o755)
ns='ops-native-v12-r24-20261026';name='ops-r49-log-collector'
tenant='01a177f1-372f-75b7-be90-e8121d1445f5';cluster='79014400-9453-4cb4-9678-0fae47981d79'
password=secrets.token_hex(32);(private/'http-password').write_text(password);os.chmod(private/'http-password',0o600)
(private/'source-http.json').write_text(json.dumps({'schemaVersion':'ops-source-http-credentials/v1','mode':'basic','username':'r49-archive','password':password}));os.chmod(private/'source-http.json',0o600)
subprocess.run(['openssl','req','-x509','-newkey','ec','-pkeyopt','ec_paramgen_curve:P-256','-nodes','-days','30','-subj','/CN=r49-task-log-archive','-addext','subjectAltName=IP:127.0.0.1,DNS:localhost','-keyout',str(private/'tls.key'),'-out',str(private/'tls.crt')],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL);os.chmod(private/'tls.key',0o600)
subprocess.run(['docker','run','-d','--name','ops-v12-r49-victorialogs','--restart','unless-stopped','--read-only','--cap-drop','ALL','--security-opt','no-new-privileges','--pids-limit','64','--memory','512m','--cpus','1','-p','127.0.0.1:19438:9428','--mount',f'type=bind,source={private},target=/private,readonly','--mount',f'type=bind,source={work/"victoria-data"},target=/victoria-logs-data','ops.local/amd64-poc/victoria-logs:v1.52.0','-httpListenAddr=:9428','-tls','-tlsCertFile=/private/tls.crt','-tlsKeyFile=/private/tls.key','-httpAuth.username=r49-archive','-httpAuth.password=file:///private/http-password','-retentionPeriod=30d'],check=True,stdout=subprocess.DEVNULL)
objects=[{'apiVersion':'v1','kind':'ServiceAccount','metadata':{'name':name,'namespace':ns}}, {'apiVersion':'rbac.authorization.k8s.io/v1','kind':'ClusterRole','metadata':{'name':name},'rules':[{'apiGroups':[''],'resources':['pods','namespaces'],'verbs':['get','list','watch']},{'apiGroups':[''],'resources':['nodes'],'resourceNames':['mssc'],'verbs':['get']}]}, {'apiVersion':'rbac.authorization.k8s.io/v1','kind':'ClusterRoleBinding','metadata':{'name':name},'roleRef':{'apiGroup':'rbac.authorization.k8s.io','kind':'ClusterRole','name':name},'subjects':[{'kind':'ServiceAccount','name':name,'namespace':ns}]}]
args=['-kubernetesCollector','-httpListenAddr=127.0.0.1:19429','-tmpDataPath=/data','-remoteWrite.url=https://127.0.0.1:19438/insert/native','-remoteWrite.basicAuth.username=r49-archive','-remoteWrite.basicAuth.passwordFile=/private/http-password','-remoteWrite.tlsCAFile=/private/tls.crt','-remoteWrite.maxDiskUsagePerURL=1GB','-remoteWrite.queues=1','-kubernetesCollector.includePodLabels=false','-kubernetesCollector.excludeFilter=NOT kubernetes.pod_namespace:'+json.dumps(ns)+' OR kubernetes.pod_name:~"ops-r49-log-collector-.*"','-kubernetesCollector.extraFields='+json.dumps({'tenant':tenant,'cluster':cluster,'collector':'vlagent-kubernetes/v1'}),'-kubernetesCollector.streamFields=tenant,cluster,collector,kubernetes.pod_namespace,kubernetes.pod_uid,kubernetes.container_name']
vols=[('bin',str(work/'bin'),'/ops',True),('state',str(work/'collector-data'),'/data',False),('private',str(private),'/private',True),('containers','/var/log/containers','/var/log/containers',True),('pods','/var/log/pods','/var/log/pods',True)]
# Only the two collector credential files are mounted; TLS private key remains host-only.
subprocess.run(['kubectl','create','secret','generic',name,'-n',ns,'--from-file=http-password='+str(private/'http-password'),'--from-file=tls.crt='+str(private/'tls.crt')],check=True,stdout=subprocess.DEVNULL)
volumes=[{'name':n,'secret':{'secretName':name}} if n=='private' else {'name':n,'hostPath':{'path':p,'type':'Directory'}} for n,p,m,r in vols]
container={'name':'collector','image':json.loads(subprocess.check_output(['kubectl','get','pod','ops-worker','-n',ns,'-o','json']))['spec']['containers'][0]['image'],'imagePullPolicy':'Never','command':['/ops/vlagent'],'args':args,'env':[{'name':'POD_NAME','valueFrom':{'fieldRef':{'fieldPath':'metadata.name'}}}],'securityContext':{'runAsUser':0,'allowPrivilegeEscalation':False,'readOnlyRootFilesystem':True,'capabilities':{'drop':['ALL']}},'resources':{'requests':{'cpu':'50m','memory':'128Mi'},'limits':{'cpu':'1','memory':'512Mi'}},'volumeMounts':[{'name':n,'mountPath':m,'readOnly':r}for n,p,m,r in vols]}
objects.append({'apiVersion':'apps/v1','kind':'DaemonSet','metadata':{'name':name,'namespace':ns},'spec':{'selector':{'matchLabels':{'app':name}},'template':{'metadata':{'labels':{'app':name}},'spec':{'serviceAccountName':name,'hostNetwork':True,'dnsPolicy':'ClusterFirstWithHostNet','nodeSelector':{'kubernetes.io/hostname':'mssc'},'containers':[container],'volumes':volumes,'terminationGracePeriodSeconds':30}}}})
(work/'collector-resources.json').write_text(json.dumps({'apiVersion':'v1','kind':'List','items':objects},indent=2))
subprocess.run(['kubectl','apply','-f',str(work/'collector-resources.json')],check=True,stdout=subprocess.DEVNULL)
(work/'collector-start.json').write_text(json.dumps({'startedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'tenantId':tenant,'clusterUid':cluster,'namespace':ns,'collectorVersion':'v1.52.0-ops1','coverageComplete':False,'endpoint':'https://127.0.0.1:19438','authRef':'openbao://secret/data/ops/r49-victorialogs/source'},indent=2))
print('r49 archive and scoped persistent collector created')
